// Clean deduplicated arrays filtered strictly by exact length and A-Z
function sanitizeList(raw: string[], length: number): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const re = new RegExp(`^[A-Z]{${length}}$`);
  for (const w of raw) {
    const clean = w.trim().toUpperCase();
    if (re.test(clean) && !seen.has(clean)) {
      seen.add(clean);
      out.push(clean);
    }
  }
  return out;
}

export const SOLUTION_WORDS: Record<WordLength, string[]> = {
  4: sanitizeList(RAW_SOLUTIONS_4, 4),
  5: sanitizeList(RAW_SOLUTIONS_5, 5),
  6: sanitizeList(RAW_SOLUTIONS_6, 6),
};

